import * as flatbuffers from 'flatbuffers'

import { Action, Change, Entity, Input, Snapshot, Update } from '../flatbuffers/generated.mjs'
import { KINDS, STANCES } from '../workloads.mjs'

export const name = 'flatbuffers (read in place)'
export const pkg = 'flatbuffers'
export const kind = 'schema'
export const notes =
  'code generated by flatc 25.12.19 from flatbuffers/messages.fbs; one Builder, cleared for each message; the ' +
  'reader builds no object: it reads every field through the accessors; optional scalars; t as ulong (BigInt)'

const KIND_INDEX = Object.fromEntries(KINDS.map((value, i) => [value, i]))
const STANCE_INDEX = Object.fromEntries(STANCES.map((value, i) => [value, i]))
const builder = new flatbuffers.Builder(8192)

export const encodeSnapshot = message => {
  builder.clear()
  const { entities } = message
  const offsets = []
  for (let i = 0; i < entities.length; i++) {
    const entity = entities[i]
    const id = builder.createString(entity.id)
    const label = builder.createString(entity.name)
    offsets.push(
      Entity.createEntity(
        builder,
        id,
        label,
        KIND_INDEX[entity.kind],
        entity.x,
        entity.y,
        entity.rot,
        entity.health,
        entity.maxHealth,
        entity.mana,
        entity.level,
        entity.alive,
      ),
    )
  }
  const vector = Snapshot.createEntitiesVector(builder, offsets)
  builder.finish(Snapshot.createSnapshot(builder, BigInt(message.t), vector))
  return builder.asUint8Array().slice()
}

export const encodeUpdate = message => {
  builder.clear()
  const { updates } = message
  const offsets = []
  for (let i = 0; i < updates.length; i++) {
    const change = updates[i]
    const id = builder.createString(change.id)
    Change.startChange(builder)
    Change.addId(builder, id)
    if (change.x !== undefined) Change.addX(builder, change.x)
    if (change.y !== undefined) Change.addY(builder, change.y)
    if (change.rot !== undefined) Change.addRot(builder, change.rot)
    if (change.vx !== undefined) Change.addVx(builder, change.vx)
    if (change.vy !== undefined) Change.addVy(builder, change.vy)
    if (change.health !== undefined) Change.addHealth(builder, change.health)
    if (change.mana !== undefined) Change.addMana(builder, change.mana)
    if (change.stance !== undefined) Change.addStance(builder, STANCE_INDEX[change.stance])
    offsets.push(Change.endChange(builder))
  }
  const vector = Update.createUpdatesVector(builder, offsets)
  builder.finish(Update.createUpdate(builder, BigInt(message.t), message.ack, vector))
  return builder.asUint8Array().slice()
}

export const encodeInput = message => {
  builder.clear()
  const { actions } = message
  const offsets = []
  for (let i = 0; i < actions.length; i++) {
    const action = actions[i]
    const ability = builder.createString(action.ability)
    const target = action.target === undefined ? 0 : builder.createString(action.target)
    Action.startAction(builder)
    Action.addAbility(builder, ability)
    if (target !== 0) Action.addTarget(builder, target)
    offsets.push(Action.endAction(builder))
  }
  const vector = Input.createActionsVector(builder, offsets)
  const zone = builder.createString(message.zone)
  builder.finish(
    Input.createInput(
      builder,
      message.seq,
      BigInt(message.t),
      message.x,
      message.y,
      message.vx,
      message.vy,
      message.rot,
      zone,
      vector,
    ),
  )
  return builder.asUint8Array().slice()
}

let read = 0
const entityAt = new Entity()
const changeAt = new Change()
const actionAt = new Action()

const snapshot = {
  encode: encodeSnapshot,
  decode: data => {
    const root = Snapshot.getRootAsSnapshot(new flatbuffers.ByteBuffer(data))
    let sum = root.t() === 0n ? 0 : 1
    for (let i = 0, n = root.entitiesLength(); i < n; i++) {
      const entity = root.entities(i, entityAt)
      sum += entity.id().length + entity.name().length + entity.kind() + entity.x() + entity.y() + entity.rot()
      sum += entity.health() + entity.maxHealth() + entity.mana() + entity.level() + (entity.alive() ? 1 : 0)
    }
    read += sum
    return root
  },
  view: root => ({
    t: Number(root.t()),
    entities: Array.from({ length: root.entitiesLength() }, (_, i) => {
      const entity = root.entities(i)
      return {
        id: entity.id(),
        name: entity.name(),
        kind: KINDS[entity.kind()],
        x: entity.x(),
        y: entity.y(),
        rot: entity.rot(),
        health: entity.health(),
        maxHealth: entity.maxHealth(),
        mana: entity.mana(),
        level: entity.level(),
        alive: entity.alive(),
      }
    }),
  }),
}

const OPTIONAL = ['x', 'y', 'rot', 'vx', 'vy', 'health', 'mana']

const update = {
  encode: encodeUpdate,
  decode: data => {
    const root = Update.getRootAsUpdate(new flatbuffers.ByteBuffer(data))
    let sum = (root.t() === 0n ? 0 : 1) + root.ack()
    for (let i = 0, n = root.updatesLength(); i < n; i++) {
      const change = root.updates(i, changeAt)
      sum += change.id().length
      sum += (change.x() ?? 0) + (change.y() ?? 0) + (change.rot() ?? 0) + (change.vx() ?? 0) + (change.vy() ?? 0)
      sum += (change.health() ?? 0) + (change.mana() ?? 0) + (change.stance() ?? 0)
    }
    read += sum
    return root
  },
  view: root => ({
    t: Number(root.t()),
    ack: root.ack(),
    updates: Array.from({ length: root.updatesLength() }, (_, i) => {
      const change = root.updates(i)
      const out = { id: change.id() }
      for (const field of OPTIONAL) if (change[field]() !== null) out[field] = change[field]()
      if (change.stance() !== null) out.stance = STANCES[change.stance()]
      return out
    }),
  }),
}

const input = {
  encode: encodeInput,
  decode: data => {
    const root = Input.getRootAsInput(new flatbuffers.ByteBuffer(data))
    let sum = root.seq() + (root.t() === 0n ? 0 : 1) + root.x() + root.y() + root.vx() + root.vy() + root.rot()
    sum += root.zone().length
    for (let i = 0, n = root.actionsLength(); i < n; i++) {
      const action = root.actions(i, actionAt)
      sum += action.ability().length + (action.target()?.length ?? 0)
    }
    read += sum
    return root
  },
  view: root => ({
    seq: root.seq(),
    t: Number(root.t()),
    x: root.x(),
    y: root.y(),
    vx: root.vx(),
    vy: root.vy(),
    rot: root.rot(),
    zone: root.zone(),
    actions: Array.from({ length: root.actionsLength() }, (_, i) => {
      const action = root.actions(i)
      return action.target() === null
        ? { ability: action.ability() }
        : { ability: action.ability(), target: action.target() }
    }),
  }),
}

export const fieldsRead = () => read
export const workloads = { snapshot: () => snapshot, update: () => update, input: () => input }
